-- IUFyou import (this is the script that was run on the IUFU project on 2026-11-01).
-- 1) backs up existing public.videos rows, 2) hides (does not delete) them, 3) imports the live site list from content.js (2026-10-22), order preserved.
-- Safe to re-run: skipped if live shorts already exist.
do $do$
begin
  if exists (select 1 from public.videos where published and kind = 'short') then
    raise notice 'live shorts already imported; skipped';
    return;
  end if;
  if to_regclass('public.videos_backup_20261101') is null then
    create table public.videos_backup_20261101 as select * from public.videos;
    alter table public.videos_backup_20261101 enable row level security;
  end if;
  update public.videos set published = false, updated_at = now() where published;
  insert into public.videos(kind,youtube_id,title,position,published,published_at)
  select kind,youtube_id,title,position,true,now()
